$ cc -std=c11 -O2 -Wall -Wextra -Wpedantic -Werror layout_demo.c -o layout_demo
$ ./layout_demo row
row,536346624,0.000806000,4
$ ./layout_demo column
column,536346624,0.005436000,4
$ ./layout_demo diag; echo "exit=$?"
usage: layout_demo row|column
exit=2
```

