<- {"jsonrpc": "2.0", "id": 1, "result": {"protocolVersion": "2025-11-25", "capabilities": {"tools": {}, "resources": {}}, "serverInfo": {"name": "metrics-server", "version": "0.1.0"}}}
-> {"jsonrpc": "2.0", "method": "notifications/initialized"}
